args.old_string:
# Check if this is a sequence delimiter item
if tag == SequenceDelimiterTag:
    length = fp.read_UL()  # Read the length (should be 0)
    if length != 0:
        raise ValueError(
            f"Sequence Delimiter Item has non-zero length ({length})"
        )
    return None  # End of sequence

# Not a sequence delimiter, should be an item tag
if tag != ItemTag:
    raise ValueError(
        f"Expected Item Tag (FFFE,E000) but got {tag} at position 0x{fp.tell()-4:x}"
    )

length = fp.read_UL()
if length == 0xFFFFFFFF:
    raise ValueError(
        f"Undefined length Item at position 0x{fp.tell()-4:x}"
    )

args.new_string:
# Check if this is a sequence delimiter item
if tag == SequenceDelimiterTag:
    length = fp.read_UL()  # Read the length (should be 0)
    if length != 0:
        warn_and_log(
            f"Expected 0x00000000 after delimiter, found 0x{length:X}, "
            f"at position 0x{fp.tell() - 4:x}"
        )
    return None  # End of sequence

if tag != ItemTag:
    warn_and_log(
        f"Expected item with tag {ItemTag} at file position "
        f"0x{fp.tell() - 4:x}"
    )

length = fp.read_UL()
if length == 0xFFFFFFFF:
    raise ValueError(
        "Encapsulated data fragment had Undefined "
        f"Length at data position 0x{fp.tell() - 4:x}"
    )
